head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vScrenProcTpCd = "";
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
// 세션정보를 얻기위한 함수사용

scwin.getPar, scwin.setPar;
scwin.Isur_cd = "", scwin.Isur_nm = "", scwin.Secugrp_id = "", scwin.Mkt_id = "", scwin.fr_bz_procs_no = "";
scwin.TR_JOB;
scwin.vSECT_CHG_TP_CD;
scwin.vAFCHG_SECT_TP_CD;
scwin.vBFCHG_SECT_TP_CD;
scwin.vCHG_DD;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        const fnc = $c.frame.path("../").scwin.getPar; // Provider화면에서 fn_GetPar명칭으로 선언된 함수를 획득
        const arrPar = new Array();
        $c.elw.fn_searchCode();
        if (fnc !== undefined) {
            fnc(arrPar); // Provider화면의 callback함수를 호출하여 필요한 인수를 넘겨받는다.
            scwin.Isur_cd = (arrPar.length >= 1 ? arrPar[0] : ""); // 발행기관코드
            scwin.Isur_nm = (arrPar.length >= 2 ? arrPar[1] : ""); // 발행기관명
            scwin.Secugrp_id = (arrPar.length >= 3 ? arrPar[2] : ""); // 증권그룹ID
            scwin.Mkt_id = (arrPar.length >= 4 ? arrPar[3] : ""); // 시장구분코드
            scwin.fr_bz_procs_no = (arrPar.length >= 5 ? arrPar[4] : ""); // 업무처리번호(수정시만 유효)

        }
        buttonSet.setSaveInfo(btn_Save, scwin.save); // 저장
        buttonSet.setUpdateInfo(btn_Update, scwin.update); // 수정
        buttonSet.setDeleteInfo(btn_Delete, scwin.delete); // 삭제
        buttonSet.setDsclInfo(btn_Dscl, scwin.dscl); // 안내문작성
        buttonSet.setDrftInfo(btn_Drft, scwin.drft); // 기안
        if (scwin.fr_bz_procs_no !== "") {
            // Provider화면 에서 넘겨받은 업무처리번호가 ""가 아니라면 신규작성으로 간주한다.
            await scwin.readSync();
        } else {
            await scwin.bfSectTpCd();
        }
        $c.cm.PanelToGroupBox(panel_Top);

        // buttonSet.setButtonDepCd(dts_ByCorpDepCd, txb_ISUR_CD.value, js_dep_cd);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05244.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_Item_OnLoadError
 * @description dts_Item 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_Item_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_Item);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05244.dts_Item_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_Item_OnLoadCompleted
 * @description dts_Item 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_Item_OnLoadCompleted = function(rowcount) {
    try {
        txb_ISUR_CD.setValue(scwin.Isur_cd);
        txb_COM_NM.setValue(scwin.Isur_nm);
        scwin.vSECT_CHG_TP_CD = dts_Item.getCellData(1, "SECT_CHG_TP_CD");
        scwin.vAFCHG_SECT_TP_CD = dts_Item.getCellData(1, "AFCHG_SECT_TP_CD");
        scwin.vBFCHG_SECT_TP_CD = dts_Item.getCellData(1, "BFCHG_SECT_TP_CD");
        scwin.vCHG_DD = dts_Item.getCellData(1, "CHG_DD");
        // 조회가 완료되었을때 신규처리에 의한 조회인지,  수정에 의한 조회인지를 구별
        if (dts_Item.getCellData(dts_Item.getRowPosition(), "BZ_PROCS_NO") === "") {
            buttonSet.setInsertStatus();
        } else {
            let vCurDate = $c.ut.cGetToday("yyyymmdd");
            if (vCurDate <= edt_CHG_DD.getValue()) {
                buttonSet.setUpdateStatus();
            } else {
                buttonSet.setErrorStatus(); // disable 시킨다.
                // alert('[DISCLS_YN]'+dts_IndustryChange.NameValue(1, "DISCLS_YN"));
                // setButtonSetWithDate2(dts_Item.NameValue(1, "DISCLS_YN"));

            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05244.dts_Item_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {void}
 * @hidden N
 */
scwin.trs_Save_OnFail = function() {
    try {
        $c.lc.fn_alertMsg('F');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05244.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        $c.lc.fn_alertMsg('S');
        scwin.parentRefresh();
        if (buttonSet.status === "D") {
            // 삭제처리의 응답인 경우
            await $c.win.closePopup();
        } else {
            await scwin.readSync();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05244.trs_Save_OnSuccess" });
    }
};

