 */
scwin.dts_BZ_CHECK_OnLoadError = async function() {
    try {
        4;
        await $c.win.alert(dts_BZ_CHECK);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05244.dts_BZ_CHECK_OnLoadError" });
