};

/**
 * @method
 * @name cmb_AFCHG_SECT_TP_CD_onselchange
 * @description cmb_AFCHG_SECT_TP_CD onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_AFCHG_SECT_TP_CD_onselchange = function() {
    try {
        if (cmb_AFCHG_SECT_TP_CD.getValue() === "X") {
            edt_SECT_END_DD.setValue("99991231");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05244.cmb_AFCHG_SECT_TP_CD_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchCode
 * @description search Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchCode = async function() {
    /*
    00726 - 소속부유형코드
    01361 - 소속부변경구분코드
    01362 - 벤처유형코드
     */
    const arrCid = [{
        cid: "SECT_TP_CD",
        cnm: "cmb_BFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_TP_CD",
        cnm: "cmb_AFCHG_SECT_TP_CD"
    }, {
        cid: "SECT_CHG_TP_CD",
        cnm: "cmb_SECT_CHG_TP_CD"
    }];
    let objCod;
    const sbmOptions = {
        id : "sbm_dts_Cod",
        action : "/CodeAction.do",
        ref : "",
        target : "dts_Cod=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    let strCbd = "",
        i, j;
    for (i = 0; i < arrCid.length; i++) {
        objCod = document.getElementById(arrCid[i].cnm);
        // alert('[objCod]'+objCod);
        if (objCod === null) {
            await $c.win.alert(arrCid[i].cnm);
        }
        strCbd = "";
        for (j = 1; j <= dts_Cod.getRowCount(); j++) {
            if (dts_Cod.getCellData(j, "CD_ENG_NM") === arrCid[i].cid) {
                if (arrCid[i].cid === "SECT_TP_CD") {
                    if (j === 1) {
                        strCbd = strCbd + (strCbd === "" ? "" : ",") + '' + "^" + '=====================================';
                    }
                    if (dts_Cod.getCellData(j, "VALUE") === "X" || dts_Cod.getCellData(j, "VALUE") === "Y" || dts_Cod.getCellData(j, "VALUE") === "W") {
                        strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                    }
                } else {
                    strCbd = strCbd + (strCbd === "" ? "" : ",") + dts_Cod.getCellData(j, "VALUE") + "^" + dts_Cod.getCellData(j, "TEXT");
                }
            }
        }
        objCod.CBData = strCbd;
    }
};

/**
 * @method
 * @name readSync
 * @description read Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.readSync = async function() {
    url += "&BZ_PROCS_NO=" + scwin.fr_bz_procs_no;
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/SectionTypeChange.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name bfSectTpCd
 * @description bf Sect Tp Cd 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bfSectTpCd = async function() {
    const sbmOptions = {
        id : "sbm_dts_Item",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Item=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name duplicateCheck
 * @description duplicate Check 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.duplicateCheck = async function() {
    url += "&ISUR_CD=" + txb_ISUR_CD.getValue();
    url += "&CHG_DD=" + edt_CHG_DD.getValue();
    const sbmOptions = {
        id : "sbm_dts_DUP_CHK",
        action : "/SectionTypeChange.do",
        ref : "",
        target : "dts_DUP_CHK=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return dts_DUP_CHK.getCellData(1, "DUP_CHK");
};

/**
 * @method
 * @name trs
 * @description trs 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs = async function() {
    if (scwin.TR_JOB === "I") {
        scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_02;
    } else if (scwin.TR_JOB === "U") {
        scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_03;
    } else if (scwin.TR_JOB === "D") {
        scwin.vScrenProcTpCd = SCREN_PROCS_TP_CD_04;
    }
    trs_Save.KeyName = "toinb_dataid4";
    const sbmOptions = {
        id : "sbm_trs_Save",
        action : "/SectionTypeChange.do",
        ref : "dts_Item",
        target : "trs_Save=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)
};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkForm
 * @description check Form 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkForm = async function() {
    let vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (txb_ISUR_CD.getValue() === "") {
        await $c.win.alert("[회사코드] 항목값이  없습니다.");
        txb_ISUR_CD.focus();
        return false;
    }
    if (cmb_SECT_CHG_TP_CD.getValue() === "") {
        await $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (scwin.vSECT_CHG_TP_CD === 'N') {
        if (scwin.vSECT_CHG_TP_CD !== cmb_SECT_CHG_TP_CD.getValue()) {
            await $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [소속부변경구분]항목을 변경할 수 없습니다.");
            cmb_SECT_CHG_TP_CD.focus();
            return false;
            // 심사팀에서 신규상장시 입력한 자료라서 수정 불가.
        }
        if (scwin.vBFCHG_SECT_TP_CD !== cmb_BFCHG_SECT_TP_CD.getValue()) {
            await $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [변경전소속부]항목을 변경할 수 없습니다.");
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
        if (scwin.vAFCHG_SECT_TP_CD !== cmb_AFCHG_SECT_TP_CD.getValue()) {
            await $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [변경후소속부]항목을 변경할 수 없습니다.");
            cmb_AFCHG_SECT_TP_CD.focus();
            return false;
        }
        if (scwin.vCHG_DD !== edt_CHG_DD.getValue()) {
            await $c.win.alert("[소속부변경구분]값이 '신규상장'이면 [변경일]항목을 변경할 수 없습니다.");
            edt_CHG_DD.focus();
            return false;
        }
    }
    if (cmb_BFCHG_SECT_TP_CD.getValue() === 'X' && (cmb_AFCHG_SECT_TP_CD.getValue() === 'Y' || cmb_AFCHG_SECT_TP_CD.getValue() === 'W')) {
        await $c.win.alert("[일반기업부]에서 [스타트업기업부] 또는 [크라우드펀딩기업부]로 소속부유형을 변경할 수 없습니다.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if (cmb_BFCHG_SECT_TP_CD.getValue() === 'Y') {
        if (cmb_AFCHG_SECT_TP_CD.getValue() === 'W') {
            await $c.win.alert("[스타트업기업부]에서 [크라우드펀딩기업부]로 소속부유형을 변경할 수 없습니다.");
            return false;
        }
    } else if (cmb_BFCHG_SECT_TP_CD.getValue() === 'W') {
        if (cmb_AFCHG_SECT_TP_CD.getValue() === 'Y') {
            await $c.win.alert("[크라우드펀딩기업부]에서 [스타트업기업부]로 소속부유형을 변경할 수 없습니다.");
            return false;
        }
    }
    if (cmb_SECT_CHG_TP_CD.getValue() === "") {
        await $c.win.alert("[소속부변경구분]을 선택하세요.");
        cmb_SECT_CHG_TP_CD.focus();
        return false;
    }
    if (cmb_SECT_CHG_TP_CD.getValue() !== "N") {
        // 신규상장이 아닐 경우
        if (cmb_BFCHG_SECT_TP_CD.getValue() === "") {
            await $c.win.alert("[변경전 소속부] 항목값이  없습니다.");
            cmb_BFCHG_SECT_TP_CD.focus();
            return false;
        }
    }
    if (cmb_AFCHG_SECT_TP_CD.getValue() === "") {
        await $c.win.alert("[변경후 소속부]를 선택하세요.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if (cmb_BFCHG_SECT_TP_CD.getValue() === cmb_AFCHG_SECT_TP_CD.getValue()) {
        await $c.win.alert("[변경전 소속부]와 [변경후 소속부]가 동일합니다.");
        cmb_AFCHG_SECT_TP_CD.focus();
        return false;
    }
    if (edt_CHG_DD.getValue() === "") {
        await $c.win.alert("[변경일]을 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (vCurDate >= edt_CHG_DD.getValue()) {
        await $c.win.alert("[변경일]을 현재일이후로 입력하세요.");
        edt_CHG_DD.focus();
        return false;
    }
    if (edt_SECT_STRT_DD.getValue() === "") {
        if (edt_SECT_END_DD.getValue() !== "") {
            await $c.win.alert("[소속부유효시작일]을 입력하세요.");
            edt_SECT_STRT_DD.focus();
            return false;
        }
    } else {
        if (edt_SECT_END_DD.getValue() === "") {
            await $c.win.alert("[소속부유효종료일]을 입력하세요.");
            edt_SECT_END_DD.focus();
            return false;
        }
        if (parseInt(edt_SECT_STRT_DD.getValue(), 10) > parseInt(edt_SECT_END_DD.getValue(), 10)) {
            await $c.win.alert("[소속부유효종료일]은 [소속부유효시작일]보다 작아야 합니다. 다시 입력해주세요");
            return false;
        }
    }
    return true;
};

